/* Wrapper for cladiv */
lapack_complex_float FC_GLOBAL(cladiv,CLADIV)
    (lapack_complex_float *x, lapack_complex_float *y)
{
    lapack_complex_float (*fn) (void *x, void *y);
    void (*fn_intel) (lapack_complex_float *ret, void *x, void *y);

    #ifdef FLEXIBLAS_HOOK_API
    lapack_complex_float (*fn_hook) (void *x, void *y);
    void (*fn_intel_hook) (lapack_complex_float *ret, void *x, void *y);
    hook_pos_cladiv = 0;
    #endif
    lapack_complex_float ret;

    /* Post init if necessary */
    if ( unlikely(current_backend->post_init != 0) ) {
        __flexiblas_backend_init(current_backend);
        current_backend->post_init = 0;
    }

    *(void **) &fn = current_backend->lapack.cladiv;
    *(void **) &fn_intel = current_backend->lapack.cladiv;

    #ifdef FLEXIBLAS_HOOK_API
    *(void **) &fn_hook = __flexiblas_hooks->cladiv.hook_function[0];
    *(void **) &fn_intel_hook = __flexiblas_hooks->cladiv.hook_function[0];

    if ( fn_hook != NULL) {
        if(current_backend->info.intel_interface == 0 ) {
            ret = fn_hook((void *) x, (void *) y);
        } else {
            fn_intel_hook( &ret, (void *) x, (void *) y);
        }
    } else {
        if(current_backend->info.intel_interface == 0 ) {
            ret = fn((void *) x, (void *) y);
        } else {
            fn_intel( &ret, (void *) x, (void *) y);
        }
    }
    #else
    if(current_backend->info.intel_interface == 0 ) {
        ret = fn((void *) x, (void *) y);
    } else {
        fn_intel( &ret, (void *) x, (void *) y);
    }
    #endif
    return ret;
}

