/* Wrapper for slapy2 */
float FC_GLOBAL(slapy2,SLAPY2)
    (float *x, float *y)
{
    float (*fn) (void *x, void *y);
    #ifdef FLEXIBLAS_HOOK_API
    float (*fn_hook) (void *x, void *y);
    hook_pos_slapy2 = 0;
    #endif
    float ret;

    /* Post init if necessary */
    if ( unlikely(current_backend->post_init != 0) ) {
        __flexiblas_backend_init(current_backend);
        current_backend->post_init = 0;
    }

    if ( current_backend->info.f2c_float_return == 1) {
         double (*fn_double) (void *x, void *y);
         *(void **) &fn_double = current_backend->lapack.slapy2;
         #ifdef FLEXIBLAS_HOOK_API
         *(void **) &fn_hook = __flexiblas_hooks->slapy2.hook_function[0];

         if ( fn_hook != NULL ) {
             ret = fn_hook((void *) x, (void *) y);
         } else {
             ret = (float) fn_double((void *) x, (void *) y);
         }
         #else
         ret = fn((void *) x, (void *) y);
         #endif

    } else {

         *(void **) &fn = current_backend->lapack.slapy2;
         #ifdef FLEXIBLAS_HOOK_API
         *(void **) &fn_hook = __flexiblas_hooks->slapy2.hook_function[0];

         if ( fn_hook != NULL ) {
             ret = fn_hook((void *) x, (void *) y);
         } else {
             ret = fn((void *) x, (void *) y);
         }
         #else
         ret = fn((void *) x, (void *) y);
         #endif
    }
    return ret;
}

